#!/usr/bin/env python3
from pathlib import Path
import sys

root = Path(sys.argv[1]).resolve() if len(sys.argv) > 1 else Path('build/PrePoMax-CodeAster').resolve()

vtk = root / 'vtkControl' / 'vtkControl.cs'
text = vtk.read_text(encoding='utf-8-sig')
anchor = '''        // Callbacks                                                                                                                \n'''
helper = '''        // AsterMax C8.74b diagnostic seam. It classifies the live rendered contour\n        // geometry against undeformed, true-scale and x10 result coordinates, and also\n        // measures the x10 residual after explicit IEEE-754 float32 coordinate quantization.\n        // This is read-only: it does not mutate actors, mesh, camera, results, or solver data.\n        public void AsterMaxGetVisibleContourScaleDiagnosticsForQualification(double[][] expectedScale0,\n                                                                               double[][] expectedScale1,\n                                                                               double[][] expectedScale10,\n                                                                               double[][] requiredScale10,\n                                                                               out int actorCount,\n                                                                               out long renderedPointCount,\n                                                                               out double scale0MaxError,\n                                                                               out double scale1MaxError,\n                                                                               out double scale10RawMaxError,\n                                                                               out double scale10Float32MaxError,\n                                                                               out double requiredRawMaxError,\n                                                                               out double requiredFloat32MaxError)\n        {\n            if (expectedScale0 == null || expectedScale1 == null || expectedScale10 == null ||\n                expectedScale0.Length == 0 || expectedScale1.Length != expectedScale0.Length ||\n                expectedScale10.Length != expectedScale0.Length)\n                throw new ArgumentException("C8.74b expected coordinate sets are missing or inconsistent.");\n\n            actorCount = 0;\n            renderedPointCount = 0;\n            scale0MaxError = 0;\n            scale1MaxError = 0;\n            scale10RawMaxError = 0;\n            scale10Float32MaxError = 0;\n            requiredRawMaxError = 0;\n            requiredFloat32MaxError = 0;\n            List<double[]> renderedPoints = new List<double[]>();\n\n            foreach (vtkMaxActor actor in _actors.Values)\n            {\n                if (actor == null || !actor.ColorContours || actor.Geometry == null) continue;\n                if (actor.Geometry.GetVisibility() != 1 || actor.Geometry.GetMapper() == null) continue;\n                vtkDataSet input = actor.Geometry.GetMapper().GetInput();\n                if (input == null) continue;\n                long n = input.GetNumberOfPoints();\n                if (n <= 0) continue;\n                actorCount++;\n                for (long i = 0; i < n; i++)\n                {\n                    double[] p = input.GetPoint(i);\n                    if (p == null || p.Length < 3) continue;\n                    renderedPoints.Add(new double[] { p[0], p[1], p[2] });\n                    renderedPointCount++;\n\n                    double nearest0 = Double.PositiveInfinity;\n                    double nearest1 = Double.PositiveInfinity;\n                    double nearest10 = Double.PositiveInfinity;\n                    double nearest10f = Double.PositiveInfinity;\n                    for (int j = 0; j < expectedScale10.Length; j++)\n                    {\n                        double[] q0 = expectedScale0[j];\n                        double[] q1 = expectedScale1[j];\n                        double[] q10 = expectedScale10[j];\n                        double dx = p[0] - q0[0]; double dy = p[1] - q0[1]; double dz = p[2] - q0[2];\n                        double d2 = dx * dx + dy * dy + dz * dz; if (d2 < nearest0) nearest0 = d2;\n                        dx = p[0] - q1[0]; dy = p[1] - q1[1]; dz = p[2] - q1[2];\n                        d2 = dx * dx + dy * dy + dz * dz; if (d2 < nearest1) nearest1 = d2;\n                        dx = p[0] - (double)(float)q10[0]; dy = p[1] - (double)(float)q10[1]; dz = p[2] - (double)(float)q10[2];\n                        d2 = dx * dx + dy * dy + dz * dz; if (d2 < nearest10f) nearest10f = d2;\n                        dx = p[0] - q10[0]; dy = p[1] - q10[1]; dz = p[2] - q10[2];\n                        d2 = dx * dx + dy * dy + dz * dz; if (d2 < nearest10) nearest10 = d2;\n                    }\n                    scale0MaxError = Math.Max(scale0MaxError, Math.Sqrt(nearest0));\n                    scale1MaxError = Math.Max(scale1MaxError, Math.Sqrt(nearest1));\n                    scale10RawMaxError = Math.Max(scale10RawMaxError, Math.Sqrt(nearest10));\n                    scale10Float32MaxError = Math.Max(scale10Float32MaxError, Math.Sqrt(nearest10f));\n                }\n            }\n\n            if (actorCount == 0 || renderedPointCount == 0)\n                throw new InvalidOperationException("No visible VTK ColorContours geometry points found for C8.74b diagnostics.");\n\n            if (requiredScale10 != null)\n            {\n                foreach (double[] q in requiredScale10)\n                {\n                    double nearestRaw = Double.PositiveInfinity;\n                    double nearestFloat = Double.PositiveInfinity;\n                    foreach (double[] p in renderedPoints)\n                    {\n                        double dx = p[0] - q[0]; double dy = p[1] - q[1]; double dz = p[2] - q[2];\n                        double d2 = dx * dx + dy * dy + dz * dz; if (d2 < nearestRaw) nearestRaw = d2;\n                        dx = p[0] - (double)(float)q[0]; dy = p[1] - (double)(float)q[1]; dz = p[2] - (double)(float)q[2];\n                        d2 = dx * dx + dy * dy + dz * dz; if (d2 < nearestFloat) nearestFloat = d2;\n                    }\n                    requiredRawMaxError = Math.Max(requiredRawMaxError, Math.Sqrt(nearestRaw));\n                    requiredFloat32MaxError = Math.Max(requiredFloat32MaxError, Math.Sqrt(nearestFloat));\n                }\n            }\n        }\n\n'''
if helper not in text:
    if anchor not in text:
        raise SystemExit('vtkControl callbacks anchor not found; refusing partial C8.74b patch.')
    text = text.replace(anchor, helper + anchor, 1)
vtk.write_text(text, encoding='utf-8')

frm = root / 'PrePoMax' / 'Forms' / 'FrmMain.cs'
f = frm.read_text(encoding='utf-8-sig')
frm_anchor = '''        public string GetDeformationVariable()\n        {\n'''
frm_helper = '''        // AsterMax C8.74b: expose read-only rendered scale diagnostics from the native VTK host.\n        public void AsterMaxGetRenderedContourScaleDiagnosticsForQualification(double[][] expectedScale0,\n                                                                                double[][] expectedScale1,\n                                                                                double[][] expectedScale10,\n                                                                                double[][] requiredScale10,\n                                                                                out int actorCount,\n                                                                                out long renderedPointCount,\n                                                                                out double scale0MaxError,\n                                                                                out double scale1MaxError,\n                                                                                out double scale10RawMaxError,\n                                                                                out double scale10Float32MaxError,\n                                                                                out double requiredRawMaxError,\n                                                                                out double requiredFloat32MaxError)\n        {\n            if (_vtk == null) throw new InvalidOperationException("VTK control is not initialized.");\n            _vtk.AsterMaxGetVisibleContourScaleDiagnosticsForQualification(expectedScale0, expectedScale1, expectedScale10, requiredScale10,\n                                                                            out actorCount, out renderedPointCount, out scale0MaxError,\n                                                                            out scale1MaxError, out scale10RawMaxError,\n                                                                            out scale10Float32MaxError, out requiredRawMaxError,\n                                                                            out requiredFloat32MaxError);\n        }\n\n'''
if frm_helper not in f:
    if frm_anchor not in f:
        raise SystemExit('FrmMain deformation getter anchor not found; refusing partial C8.74b patch.')
    f = f.replace(frm_anchor, frm_helper + frm_anchor, 1)
frm.write_text(f, encoding='utf-8')

demo = root / 'PrePoMax' / 'CodeAster' / 'CodeAsterResultsDemo.cs'
d = demo.read_text(encoding='utf-8')
old = '''                int renderedContourActorCount;\n                long renderedContourPointCount;\n                double renderedRequiredPointMaxError;\n                double renderedPointMeshMaxError = controller.Form.AsterMaxGetRenderedContourPointMatchErrorForQualification(\n                    deformedNodeCoordinates, requiredRenderedCoordinates, out renderedContourActorCount,\n                    out renderedContourPointCount, out renderedRequiredPointMaxError);\n                const double renderedPointTolerance = 1e-6;\n                if (renderedContourActorCount < 1 || renderedContourPointCount < 1)\n                    throw new InvalidDataException("C8.74 no rendered contour geometry found.");\n                if (renderedPointMeshMaxError > renderedPointTolerance)\n                    throw new InvalidDataException("C8.74 VTK mapper contains points not matching the x10 Results mesh. max_error=" + renderedPointMeshMaxError);\n                if (renderedRequiredPointMaxError > renderedPointTolerance)\n                    throw new InvalidDataException("C8.74 solver-provenance extrema nodes are not both represented in the rendered contour geometry. max_error=" + renderedRequiredPointMaxError);\n'''
new = '''                // C8.74b: diagnose the final renderer representation rather than relaxing C8.74 blindly.\n                // Build independent 0x/1x/10x coordinate hypotheses from native Results APIs, then\n                // classify the actual VTK mapper points. A second metric explicitly applies float32\n                // quantization to the expected x10 coordinates; this detects graphics-storage precision\n                // without changing or forgiving the underlying FE deformation geometry.\n                double[][] renderScale0 = new double[results.Mesh.Nodes.Count][];\n                double[][] renderScale1 = new double[results.Mesh.Nodes.Count][];\n                double[][] renderScale10 = new double[results.Mesh.Nodes.Count][];\n                int renderCoordinateIndex = 0;\n                foreach (int renderNodeId in results.Mesh.Nodes.Keys)\n                {\n                    FeNode r0 = controller.CurrentResult.UndeformedNodes[renderNodeId];\n                    FeNode r1 = controller.GetScaledNode(1f, renderNodeId);\n                    FeNode r10 = controller.GetScaledNode(10f, renderNodeId);\n                    renderScale0[renderCoordinateIndex] = new double[] { r0.Coor[0], r0.Coor[1], r0.Coor[2] };\n                    renderScale1[renderCoordinateIndex] = new double[] { r1.Coor[0], r1.Coor[1], r1.Coor[2] };\n                    renderScale10[renderCoordinateIndex] = new double[] { r10.Coor[0], r10.Coor[1], r10.Coor[2] };\n                    renderCoordinateIndex++;\n                }\n\n                int renderedContourActorCount;\n                long renderedContourPointCount;\n                double renderedScale0MaxError;\n                double renderedScale1MaxError;\n                double renderedPointMeshMaxError;\n                double renderedPointFloat32MaxError;\n                double renderedRequiredPointMaxError;\n                double renderedRequiredPointFloat32MaxError;\n                controller.Form.AsterMaxGetRenderedContourScaleDiagnosticsForQualification(\n                    renderScale0, renderScale1, renderScale10, requiredRenderedCoordinates,\n                    out renderedContourActorCount, out renderedContourPointCount,\n                    out renderedScale0MaxError, out renderedScale1MaxError,\n                    out renderedPointMeshMaxError, out renderedPointFloat32MaxError,\n                    out renderedRequiredPointMaxError, out renderedRequiredPointFloat32MaxError);\n\n                const double renderedFloat32Tolerance = 1e-6;\n                if (renderedContourActorCount < 1 || renderedContourPointCount < 1)\n                    throw new InvalidDataException("C8.74b no rendered contour geometry found.");\n                // The x10 hypothesis must be decisively closer than stale 0x or 1x geometry.\n                if (!(renderedPointMeshMaxError < renderedScale0MaxError && renderedPointMeshMaxError < renderedScale1MaxError))\n                    throw new InvalidDataException("C8.74b rendered geometry does not classify as x10. x0=" + renderedScale0MaxError + " x1=" + renderedScale1MaxError + " x10=" + renderedPointMeshMaxError);\n                // Raw double-coordinate error is retained as diagnostic evidence. Admission is based on\n                // an explicit representation test: the live VTK points must coincide with float32-quantized\n                // x10 coordinates to <=1e-6 mm. This converts the C8.74 3.05e-5 mm residual from an\n                // unexplained mismatch into a directly tested graphics-storage precision boundary.\n                if (renderedPointFloat32MaxError > renderedFloat32Tolerance)\n                    throw new InvalidDataException("C8.74b VTK points do not match float32-quantized x10 Results geometry. max_error=" + renderedPointFloat32MaxError);\n                if (renderedRequiredPointFloat32MaxError > renderedFloat32Tolerance)\n                    throw new InvalidDataException("C8.74b required extrema are not represented after float32 render quantization. max_error=" + renderedRequiredPointFloat32MaxError);\n'''
if old not in d:
    raise SystemExit('C8.74 strict runtime block not found; refusing partial C8.74b patch.')
d = d.replace(old, new, 1)

payload_old = '''                    "  \\\"rendered_viewport_point_mesh_max_error_mm\\\": " + renderedPointMeshMaxError.ToString("R", CultureInfo.InvariantCulture) + ",\\n" +\n                    "  \\\"rendered_viewport_required_extrema_max_error_mm\\\": " + renderedRequiredPointMaxError.ToString("R", CultureInfo.InvariantCulture) + ",\\n" +\n                    "  \\\"rendered_viewport_deformation_verified\\\": true,\\n" +'''
payload_new = '''                    "  \\\"rendered_viewport_scale0_max_error_mm\\\": " + renderedScale0MaxError.ToString("R", CultureInfo.InvariantCulture) + ",\\n" +\n                    "  \\\"rendered_viewport_scale1_max_error_mm\\\": " + renderedScale1MaxError.ToString("R", CultureInfo.InvariantCulture) + ",\\n" +\n                    "  \\\"rendered_viewport_point_mesh_max_error_mm\\\": " + renderedPointMeshMaxError.ToString("R", CultureInfo.InvariantCulture) + ",\\n" +\n                    "  \\\"rendered_viewport_float32_quantized_max_error_mm\\\": " + renderedPointFloat32MaxError.ToString("R", CultureInfo.InvariantCulture) + ",\\n" +\n                    "  \\\"rendered_viewport_required_extrema_max_error_mm\\\": " + renderedRequiredPointMaxError.ToString("R", CultureInfo.InvariantCulture) + ",\\n" +\n                    "  \\\"rendered_viewport_required_extrema_float32_max_error_mm\\\": " + renderedRequiredPointFloat32MaxError.ToString("R", CultureInfo.InvariantCulture) + ",\\n" +\n                    "  \\\"rendered_viewport_precision_model\\\": \\\"explicit-float32-coordinate-quantization\\\",\\n" +\n                    "  \\\"rendered_viewport_deformation_verified\\\": true,\\n" +'''
if payload_old not in d:
    raise SystemExit('C8.74 READY payload diagnostic anchor not found; refusing partial C8.74b patch.')
d = d.replace(payload_old, payload_new, 1)

demo.write_text(d, encoding='utf-8')
print(f'Patched {vtk} with C8.74b render scale/precision diagnostics')
print(f'Patched {frm} with C8.74b native VTK diagnostic bridge')
print(f'Patched {demo} with fail-closed scale classification + float32 representation admission')
